//! `vcf stats` engine and site statistics against vcftools 0.1.16 goldens
//! (`tests/golden/stats`, regenerated by `regen.sh` there).

use gloci_core::Interval;
use gloci_vcf::{
    FilterSummary, Freq, GenoDepth, Hardy, IndelHist, MaskRules, MaskedGenotypes, MissingSite,
    SampleFields, Singletons, SiteDepth, SiteMeanDepth, SiteQuality, SiteStats, SiteView,
    SnpDensity, Stat, StatSink, StatWrite, StatsEngine, TsTv, fmt_g6, site_stats_into,
    text_genotypes,
};
use std::alloc::{GlobalAlloc, Layout, System};
use std::cell::{Cell, RefCell};
use std::collections::BTreeMap;
use std::io::{self, Write};
use std::rc::Rc;

struct Counting;
thread_local! { static ALLOCS: Cell<usize> = const { Cell::new(0) }; }
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        let _ = ALLOCS.try_with(|c| c.set(c.get() + 1));
        unsafe { System.alloc(l) }
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        unsafe { System.dealloc(p, l) }
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        let _ = ALLOCS.try_with(|c| c.set(c.get() + 1));
        unsafe { System.realloc(p, l, n) }
    }
}
#[global_allocator]
static A: Counting = Counting;

type Files = BTreeMap<String, Vec<u8>>;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/stats");

/// Captures every statistic's output; `committed` lists the extensions that
/// were committed, in order.
#[derive(Default, Clone)]
struct MemSink {
    files: Rc<RefCell<BTreeMap<String, Vec<u8>>>>,
    committed: Rc<RefCell<Vec<String>>>,
}

struct MemFile {
    ext: String,
    buf: Vec<u8>,
    sink: MemSink,
}

impl Write for MemFile {
    fn write(&mut self, b: &[u8]) -> io::Result<usize> {
        self.buf.extend_from_slice(b);
        Ok(b.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl StatWrite for MemFile {
    fn commit(self: Box<Self>) -> io::Result<()> {
        self.sink.committed.borrow_mut().push(self.ext.clone());
        self.sink.files.borrow_mut().insert(self.ext, self.buf);
        Ok(())
    }
}

impl StatSink for MemSink {
    fn create(&mut self, ext: &str) -> io::Result<Box<dyn StatWrite>> {
        Ok(Box::new(MemFile {
            ext: ext.to_string(),
            buf: Vec::new(),
            sink: self.clone(),
        }))
    }
}

/// Discards everything: for the allocation test.
struct NullSink;
struct NullFile;
impl Write for NullFile {
    fn write(&mut self, b: &[u8]) -> io::Result<usize> {
        Ok(b.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}
impl StatWrite for NullFile {
    fn commit(self: Box<Self>) -> io::Result<()> {
        Ok(())
    }
}
impl StatSink for NullSink {
    fn create(&mut self, _: &str) -> io::Result<Box<dyn StatWrite>> {
        Ok(Box::new(NullFile))
    }
}

struct Vcf {
    samples: Vec<String>,
    records: Vec<String>,
}

fn load(name: &str) -> Vcf {
    let text = std::fs::read_to_string(format!("{DIR}/{name}.vcf")).unwrap();
    let mut samples = Vec::new();
    let mut records = Vec::new();
    for l in text.lines() {
        if let Some(h) = l.strip_prefix("#CHROM") {
            samples = h.split('\t').skip(9).map(str::to_string).collect();
        } else if !l.starts_with('#') {
            records.push(l.to_string());
        }
    }
    Vcf { samples, records }
}

fn span_of(line: &str) -> Interval {
    let f: Vec<&str> = line.split('\t').collect();
    let pos: u64 = f[1].parse().unwrap();
    Interval {
        start: pos - 1,
        end: pos - 1 + f[3].len() as u64,
    }
}

fn n_alleles(alts: &[u8]) -> usize {
    if alts == b"." {
        1
    } else {
        2 + alts.iter().filter(|&&c| c == b',').count()
    }
}

fn selected(v: &Vcf) -> Vec<(usize, String)> {
    v.samples.iter().cloned().enumerate().collect()
}

/// Every statistic, with the snp-density bin size given.
fn all_stats(v: &Vcf, bin: u64) -> Vec<Box<dyn Stat>> {
    vec![
        Box::new(Freq::frequencies()),
        Box::new(Freq::counts()),
        Box::new(SiteDepth::new()),
        Box::new(SiteMeanDepth::new()),
        Box::new(GenoDepth::new(selected(v))),
        Box::new(SiteQuality::new()),
        Box::new(MissingSite::new()),
        Box::new(Hardy::new()),
        Box::new(Singletons::new(selected(v))),
        Box::new(FilterSummary::new()),
        Box::new(IndelHist::new()),
        Box::new(TsTv::new()),
        Box::new(SnpDensity::new(bin)),
    ]
}

fn run(
    v: &Vcf,
    stats: Vec<Box<dyn Stat>>,
    mask: &MaskRules,
) -> Result<(Files, Vec<String>), String> {
    let sink = MemSink::default();
    let mut engine = StatsEngine::new(stats);
    let mut s = sink.clone();
    engine.start(&mut s).map_err(|e| e.to_string())?;
    let mut st = SiteStats::default();
    let mut masked = Vec::new();
    let mut fields = SampleFields::default();
    for line in &v.records {
        let site = SiteView::from_text(line.as_bytes(), span_of(line))?;
        let g = text_genotypes(line.as_bytes())?;
        site_stats_into(
            &g,
            None,
            mask,
            n_alleles(site.alts),
            &mut masked,
            &mut fields,
            &mut st,
        )?;
        let mg = MaskedGenotypes {
            inner: &g,
            masked: &masked,
        };
        engine.site(&site, Some(&mg), Some(&st))?;
    }
    engine.finish().map_err(|e| e.to_string())?;
    let files = sink.files.borrow().clone();
    let committed = sink.committed.borrow().clone();
    Ok((files, committed))
}

fn golden(prefix: &str, ext: &str) -> String {
    std::fs::read_to_string(format!("{DIR}/{prefix}.{ext}"))
        .unwrap_or_else(|e| panic!("golden {prefix}.{ext}: {e}"))
}

fn assert_same(got: &BTreeMap<String, Vec<u8>>, prefix: &str, ext: &str) {
    let g = String::from_utf8(got.get(ext).unwrap_or_else(|| panic!("no {ext}")).clone()).unwrap();
    assert_eq!(g, golden(prefix, ext), "{prefix}.{ext}");
}

const SITE_EXTS: [&str; 12] = [
    "frq",
    "frq.count",
    "ldepth",
    "ldepth.mean",
    "gdepth",
    "lqual",
    "lmiss",
    "hwe",
    "singletons",
    "FILTER.summary",
    "indel.hist",
    "TsTv.summary",
];

#[test]
fn every_statistic_matches_vcftools() {
    for name in [
        "main", "mixed", "quality", "filters", "density", "hwegrid", "hwebig", "masked",
    ] {
        let v = load(name);
        let (files, committed) = run(&v, all_stats(&v, 1000), &MaskRules::default()).unwrap();
        for ext in SITE_EXTS {
            assert_same(&files, name, ext);
        }
        assert_eq!(committed.len(), 13, "{name}: every file committed");
    }
}

#[test]
fn snp_density_matches_vcftools_bin_edges_and_empty_bins() {
    for (name, bins) in [("main", [1000u64, 7, 2500]), ("density", [1000, 7, 2500])] {
        let v = load(name);
        for bin in bins {
            let (files, _) = run(
                &v,
                vec![Box::new(SnpDensity::new(bin))],
                &MaskRules::default(),
            )
            .unwrap();
            assert_same(&files, &format!("{name}.b{bin}"), "snpden");
        }
    }
}

#[test]
fn genotype_masking_matches_vcftools() {
    let v = load("masked");
    let stats = |v: &Vcf| -> Vec<Box<dyn Stat>> {
        vec![
            Box::new(Freq::frequencies()),
            Box::new(Freq::counts()),
            Box::new(SiteDepth::new()),
            Box::new(SiteMeanDepth::new()),
            Box::new(GenoDepth::new(selected(v))),
            Box::new(MissingSite::new()),
            Box::new(Hardy::new()),
            Box::new(Singletons::new(selected(v))),
        ]
    };
    let gq = MaskRules {
        min_gq: Some(20),
        ..MaskRules::default()
    };
    let (files, _) = run(&v, stats(&v), &gq).unwrap();
    for ext in [
        "frq",
        "frq.count",
        "ldepth",
        "ldepth.mean",
        "gdepth",
        "lmiss",
        "hwe",
    ] {
        assert_same(&files, "gq20", ext);
    }
    // Intended difference (task-15-differences-draft.md): at 1:30 the only
    // G left after masking is in s2 (s1's haploid `1` is masked); vcftools
    // names the masked s1.
    let got = String::from_utf8(files["singletons"].clone()).unwrap();
    let vcftools = golden("gq20", "singletons");
    assert!(vcftools.contains("1\t30\tS\tG\ts1\n"));
    assert_eq!(
        got,
        vcftools.replace("1\t30\tS\tG\ts1\n", "1\t30\tS\tG\ts2\n")
    );
    let dp = MaskRules {
        min_dp: Some(5),
        ..MaskRules::default()
    };
    let (files, _) = run(&v, stats(&v), &dp).unwrap();
    for ext in ["ldepth.mean", "gdepth", "lmiss"] {
        assert_same(&files, "dp5", ext);
    }
}

#[test]
fn polyploid_genotypes_stop_genotype_statistics_like_vcftools() {
    let v = load("ploidy");
    for stat in [
        Box::new(Freq::frequencies()) as Box<dyn Stat>,
        Box::new(Freq::counts()),
        Box::new(MissingSite::new()),
        Box::new(Hardy::new()),
        Box::new(Singletons::new(selected(&v))),
    ] {
        let e = run(&v, vec![stat], &MaskRules::default()).unwrap_err();
        assert!(e.starts_with("1:10: polyploid"), "{e}");
    }
    // The depth, quality and whole-file statistics read through it.
    let stats: Vec<Box<dyn Stat>> = vec![
        Box::new(SiteDepth::new()),
        Box::new(SiteMeanDepth::new()),
        Box::new(GenoDepth::new(selected(&v))),
        Box::new(SiteQuality::new()),
        Box::new(FilterSummary::new()),
        Box::new(IndelHist::new()),
        Box::new(TsTv::new()),
    ];
    let (files, _) = run(&v, stats, &MaskRules::default()).unwrap();
    for ext in [
        "ldepth",
        "ldepth.mean",
        "gdepth",
        "lqual",
        "FILTER.summary",
        "indel.hist",
        "TsTv.summary",
    ] {
        assert_same(&files, "ploidy", ext);
    }
}

#[test]
fn engine_reports_what_it_needs() {
    let v = load("main");
    let e = StatsEngine::new(vec![Box::new(SiteQuality::new()), Box::new(TsTv::new())]);
    assert!(!e.needs_genotypes());
    let e = StatsEngine::new(vec![Box::new(SiteQuality::new()), Box::new(Hardy::new())]);
    assert!(e.needs_genotypes());
    assert!(StatsEngine::new(all_stats(&v, 10)).needs_genotypes());
    assert_eq!(Freq::frequencies().ext(), "frq");
    assert_eq!(Freq::counts().ext(), "frq.count");
    assert_eq!(SnpDensity::new(5).ext(), "snpden");
}

#[test]
fn rows_come_out_in_input_order_and_a_failure_names_the_record() {
    let v = load("main");
    let (files, _) = run(
        &v,
        vec![Box::new(SiteQuality::new())],
        &MaskRules::default(),
    )
    .unwrap();
    let out = String::from_utf8(files["lqual"].clone()).unwrap();
    let pos: Vec<(String, u64)> = out
        .lines()
        .skip(1)
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            (f[0].to_string(), f[1].parse().unwrap())
        })
        .collect();
    let want: Vec<(String, u64)> = v
        .records
        .iter()
        .map(|r| {
            let f: Vec<&str> = r.split('\t').collect();
            (f[0].to_string(), f[1].parse().unwrap())
        })
        .collect();
    assert_eq!(pos, want);
}

#[test]
fn site_work_does_not_allocate_after_warmup() {
    let v = load("mixed");
    let mut engine = StatsEngine::new(all_stats(&v, 1000));
    engine.start(&mut NullSink).unwrap();
    let mut st = SiteStats::default();
    let mut masked = Vec::new();
    let mut fields = SampleFields::default();
    let mask = MaskRules {
        min_gq: Some(20),
        ..MaskRules::default()
    };
    let lines: Vec<&String> = v.records.iter().collect();
    let sites: Vec<SiteView> = lines
        .iter()
        .map(|l| SiteView::from_text(l.as_bytes(), span_of(l)).unwrap())
        .collect();
    let gts: Vec<_> = lines
        .iter()
        .map(|l| text_genotypes(l.as_bytes()).unwrap())
        .collect();
    let mut pass = |engine: &mut StatsEngine| {
        for (site, g) in sites.iter().zip(&gts) {
            site_stats_into(
                g,
                None,
                &mask,
                n_alleles(site.alts),
                &mut masked,
                &mut fields,
                &mut st,
            )
            .unwrap();
            let mg = MaskedGenotypes {
                inner: g,
                masked: &masked,
            };
            engine.site(site, Some(&mg), Some(&st)).unwrap();
        }
    };
    pass(&mut engine); // warm up: buffers, map keys, hwe scratch
    let before = ALLOCS.with(Cell::get);
    for _ in 0..20 {
        pass(&mut engine);
    }
    assert_eq!(ALLOCS.with(Cell::get), before, "site work allocated");
}

#[test]
fn g6_formatting_follows_printf() {
    for (x, want) in [
        (0.5, "0.5"),
        (1.0 / 3.0, "0.333333"),
        (0.0833333333, "0.0833333"),
        (123456.789, "123457"),
        (1234567.0, "1.23457e+06"),
        (999999.5, "1e+06"),
        (1.234e-5, "1.234e-05"),
        (0.0001234, "0.0001234"),
        (100.0, "100"),
        (-3.0, "-3"),
        (1e100, "1e+100"),
        (f64::NAN, "nan"),
        (f64::INFINITY, "inf"),
        (0.0, "0"),
    ] {
        assert_eq!(fmt_g6(x), want, "{x}");
    }
}
